contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount1, uint256 amount2, address to1, address to2) public payable {
        require(amount1 > 0 && amount2 > 0, "amounts must be positive");
        require(to1 != address(0) && to2 != address(0), "beneficiaries must be non-zero");
        require(to1 != to2, "beneficiaries must be distinct");

        IERC20 mAsset = IERC20(c.depositToken());

        mAsset.transferFrom(msg.sender, address(this), amount1 + amount2);
        mAsset.approve(address(c), amount1 + amount2);

        uint256 mAssetBalBefore = mAsset.balanceOf(address(this));

        c.supplyTokenTo(amount1, to1) ;
        c.supplyTokenTo(amount2, to2) ;

        uint256 balTo1Before = c.balanceOfToken(to1);
        uint256 balTo2Before = c.balanceOfToken(to2);

        require(balTo1Before > 0 && balTo2Before > 0, "both must have credits");

        uint256 withdrawn1 = c.redeemToken(balTo1Before);

        uint256 balTo1After = c.balanceOfToken(to1);
        uint256 balTo2After = c.balanceOfToken(to2);

        uint256 mAssetBalAfter = mAsset.balanceOf(address(this));

        bool otherUnchanged = (balTo2After == balTo2Before);

        // The credits and mAssets should consistently relate: withdrawing all of to1's credits
        // must not affect to2's credit balance, and the actual mAssets returned to msg.sender
        // must match the increase in the test contract's mAsset balance.
        assert(otherUnchanged && (withdrawn1 == mAssetBalAfter - mAssetBalBefore));
    }

    receive() external payable {}
}

