        try c.supplyTokenTo(mAssetAmount, recipient) {
            creditsIssued = 1;
        } catch {
            creditsIssued = 0;
        }

        if (creditsIssued == 1) {
            uint256 recipientAfter = c.imBalances(recipient);
            assert(recipientAfter >= recipientBefore);
        }
    }

    receive() external payable {}
}

