        uint256 cBalanceBefore = mAsset.balanceOf(address(c));

        mAsset.transfer(address(c), amount);
        c.supplyTokenTo(amount, to);

        uint256 credits = c.imBalances(to);

        uint256 cBalanceMid = mAsset.balanceOf(address(c));

        bool reverted;
        uint256 returned;
        try c.redeemToken(amount) {
            reverted = false;
            returned = savings.balanceOfToken(address(c));
        } catch {
