        // what it was before (balance is monotonically non-decreasing under a successful supply), and
        // redeeming more than the caller's own credit balance must revert (redeem is bounded by the
        // caller's recorded credits, not by arbitrary token amounts).
        assert(supplyOk ? (afterBal >= beforeBal) : true);
        assert(!(redeemReverted && amountToRedeem > afterBal));
        assert(address(c).balance == 0);
    }

    receive() external payable {}
}

