    function run(uint256 amount, address to, uint256 extraSeed) public payable {
        require(to != address(0));
        require(amount > 0);

        // Use extraSeed only to make the input non-degenerate in an observable way:
        // approve the contract to pull mAsset from this test.
        c.mAsset().approve(address(c), type(uint256).max);

        // Pre-fund this test with mAsset by supplying some to itself if extraSeed allows.
        // We must not require c-state before creating it, so only use public getters after calls.
        uint256 beforeCredits = c.imBalances(to);
        uint256 beforeBalance = c.balanceOfToken(to);

        // Decide the actual amount we can supply: use the parameter amount.
        // To avoid underflow/overflow on token transfer, cap by what we can mint/seed via savings.
        // We rely only on observable behavior; call supplyTokenTo with the given amount.
        // First make sure this test holds enough mAsset: transfer directly into c is not possible,
        // instead we transfer from this test to c via SafeERC20 in supplyTokenTo using allowance.
        // The test contract may not hold mAsset; but supplyTokenTo will revert if it doesn't.
        // To keep the property meaningful even on revert, we handle both branches.
        bool reverted;
        try c.supplyTokenTo(amount, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterCredits = c.imBalances(to);

        // General rule: if the supply call succeeded, the recipient's credit balance
        // must have increased by a strictly positive amount, because savings.depositSavings
        // returns creditsIssued and the contract adds it to imBalances.
        // We express it without reading private state, only via the public getter imBalances.
        if (!reverted) {
            assert(afterCredits > beforeCredits);
        } else {
            // If it reverted, the public balance must be unchanged.
            assert(afterCredits == beforeCredits);
        }
    }

    receive() external payable {}
}

