contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 supplyAmount, uint256 redeemAmount) public payable {
        require(supplyAmount > 0);
        require(redeemAmount > 0);

        // Set up: supply to c so that msg.sender has credits.
        c.supplyTokenTo(supplyAmount, address(this));

        // Read the before balance of c in mAsset.
        uint256 beforeBalance = IERC20(c.depositToken()).balanceOf(address(c));

        // Perform the redeem. Since the fresh c has maximal allowance and
        // msg.sender has credits, this must either succeed or revert.
        bool reverted;
        try c.redeemToken(redeemAmount) returns (uint256 actual) {
            reverted = false;
            uint256 afterBalance = IERC20(c.depositToken()).balanceOf(address(c));
            // actual must equal the decrease in c's mAsset balance
            assert(actual == beforeBalance - afterBalance);
        } catch {
            reverted = true;
        }

        // General rule: the redeem either succeeds with the correct balance delta,
        // or it reverts, but it never leaves c's mAsset balance higher than before.
        if (reverted) {
            uint256 afterBalance = IERC20(c.depositToken()).balanceOf(address(c));
            assert(afterBalance <= beforeBalance);
        }
    }

    receive() external payable {}
}

