contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, address to) public {
        require(to != address(0), "to zero");

        // Snapshot before
        uint256 beforeImBal = c.imBalances(to);
        uint256 exchangeRateBefore = IERC20(c.savings()).exchangeRate();

        // Approve this contract to pull mAsset from itself so supplyTokenTo can transferFrom
        IERC20 mAsset = IERC20(c.mAsset());
        mAsset.approve(address(c), amount);

        // Perform the state-changing call (top-level)
        c.supplyTokenTo(amount, to);

        // After
        uint256 afterImBal = c.imBalances(to);
        uint256 exchangeRateAfter = IERC20(c.savings()).exchangeRate();

        // General rule: credits credited = depositSavings(amount) which is amount * 1e18 / exchangeRateBefore,
        // and imBalances were incremented by exactly that amount. Since exchangeRate may change inside
        // depositSavings (interest accrual), use the before-rate as the canonical credit minting rate.
        // The rule is: afterImBal == beforeImBal + (amount * 1e18 / exchangeRateBefore)  (modulo rounding in depositSavings).
        // We assert the exact imBalances delta equals the credits issued as observed by balanceOfToken accounting,
        // using the balanceOfToken formula: mAssets = imBalances * rate / 1e18.
        uint256 expectedCredits = (amount * 1e18) / exchangeRateBefore;

        // balanceOfToken reads current exchangeRate; verify the invariants of the accounting identity:
        // imBalances[to] increased by exactly the credits that were minted by the savings deposit.
        // Since depositSavings returns creditsIssued and exchange rate may accrue during it,
        // we use the identity: afterImBal - beforeImBal == creditsIssued == amount * 1e18 / rateUsed
        // where rateUsed is the exchange rate the savings contract used. The observable check:
        // the increase in imBalances[to] equals the increase in the underlying value divided by the rate.
        uint256 underlyingBefore = (beforeImBal * exchangeRateAfter) / 1e18;
        uint256 underlyingAfter = (afterImBal * exchangeRateAfter) / 1e18;

        // General rule: the credited imBalances increase corresponds to depositing `amount` of mAsset.
        // i.e. afterImBal >= beforeImBal and the credited credits, when converted back, equal amount (within rounding).
        // Stronger observable rule: delta in imBalances equals amount * 1e18 / exchangeRateAfter when rate is stable.
        // For a general rule that holds for ALL inputs including rate changes: the credits issued must be positive
        // when amount > 0 and the delta must be exactly the amount deposited as tracked by the savings contract.
        // We assert the monotonic accounting: afterImBal >= beforeImBal, and if amount > 0 then delta > 0,
        // and the underlying value credited equals amount (within 1 wei of rounding).
        uint256 delta = afterImBal - beforeImBal;
        uint256 underlyingDelta = (delta * exchangeRateAfter) / 1e18;

        assert(
            (amount == 0 && delta == 0) ||
            (amount > 0 && delta > 0 && underlyingDelta <= amount && amount - underlyingDelta <= 1)
        );
    }

    receive() external payable {}
}

