contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 initialDeposit, uint256 redeemAmount) public payable {
        require(initialDeposit > 0, "need deposit");
        require(redeemAmount > 0, "need redeem");

        // Setup: deposit mAsset into c, which issues credits to the caller (this test contract).
        c.mAsset().approve(address(c), initialDeposit);
        c.supplyTokenTo(initialDeposit, address(this));

        uint256 creditsBefore = c.imBalances(address(this));
        require(creditsBefore > 0, "need credits");

        // Recording values needed for the property.
        uint256 exchangeRate = c.savings().exchangeRate();
        // credits equivalent of the requested redeem amount, with rounding up as in the contract
        uint256 neededCredits = (redeemAmount * 1e18 + exchangeRate - 1) / exchangeRate;

        bool reverted;
        uint256 creditsAfter;
        uint256 balanceOfCreditsAfter;

        if (neededCredits > creditsBefore) {
            // Invalid redeem: must revert and leave state unchanged.
            try c.redeemToken(redeemAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
            creditsAfter = c.imBalances(address(this));
            // Rule: redeeming more than owned reverts and does not change credits.
            assert(reverted && creditsAfter == creditsBefore);
        } else {
            // Valid redeem: must not revert, must burn credits, and remaining credits must be non-negative.
            try c.redeemToken(redeemAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
            creditsAfter = c.imBalances(address(this));
            balanceOfCreditsAfter = c.balanceOfToken(address(this));
            // Rule: a valid redeem succeeds and never leaves the caller with more credits than before,
            // and the remaining balance of token (derived from credits) is consistent.
            assert(!reverted && creditsAfter <= creditsBefore && creditsAfter >= 0);
        }
    }

    receive() external payable {}
}

