        uint256 mAssetsActual;
        try c.redeemToken(redeemAmount) returns (uint256 actual) {
            reverted = false;
            mAssetsActual = actual;
        } catch {
            reverted = true;
        }

        uint256 creditsAfter = c.imBalances(address(this));
        uint256 balanceAfter = mAsset.balanceOf(address(this));

        // General rule: regardless of revert, the contract must never send this test contract
        // more mAsset than its remaining credits could justify, and on revert balances are unchanged.
        uint256 spentCredits = creditsBefore - creditsAfter;
        assert(
            (reverted && creditsAfter == creditsBefore && balanceAfter == balanceBefore) ||
            (!reverted && balanceAfter - balanceBefore == mAssetsActual)
        );
    }

    receive() external payable {}
}

