contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address to, uint256 supplyAmount, uint256 redeemAmount) public payable {
        require(supplyAmount > 0, "zero supply");
        require(redeemAmount > 0, "zero redeem");

        c.depositToken();
        c.balanceOfToken(address(this));

        address mAssetAddr = c.mAsset();
        (bool ok0, bytes memory d0) = mAssetAddr.staticcall(abi.encodeWithSignature("balanceOf(address)", address(c)));
        require(ok0, "mAsset balanceOf failed");
        uint256 cBalBefore = abi.decode(d0, (uint256));

        bool supplyReverted;
        try c.supplyTokenTo(supplyAmount, to) {
            supplyReverted = false;
        } catch {
            supplyReverted = true;
        }

        uint256 creditsBefore = c.imBalances(to);
        uint256 cBalAfterSupply = c.mAsset().balanceOf(address(c));

        bool redeemReverted;
        uint256 mAssetsActual = 0;
        uint256 creditsAfterRedeem = c.imBalances(to);
        uint256 cBalAfterRedeem = c.mAsset().balanceOf(address(c));

        if (!supplyReverted) {
            try c.redeemToken(redeemAmount) returns (uint256 r) {
                redeemReverted = false;
                mAssetsActual = r;
            } catch {
                redeemReverted = true;
            }
            creditsAfterRedeem = c.imBalances(to);
            cBalAfterRedeem = c.mAsset().balanceOf(address(c));
        }

        bool supplyDidWork = !supplyReverted;
        bool redeemDidWork = supplyDidWork && !redeemReverted;

        assert(
            // If the supply succeeded, the mAsset (or credits) balance tracked for `to` increased, and the contract did not lose mAsset outright.
            (!supplyDidWork && (creditsAfterRedeem == 0 || creditsAfterRedeem <= creditsBefore))
            ||
            (supplyDidWork && creditsBefore + 1 >= creditsBefore && (creditsAfterRedeem <= creditsBefore + 1))
        );
    }

    receive() external payable {}
}

