contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 supplyAmount, uint256 redeemAmount) public {
        // Supply only if the test contract actually holds enough mAsset.
        address mAssetAddr = c.depositToken();
        IERC20 m = IERC20(mAssetAddr);
        uint256 bal = m.balanceOf(address(this));
        uint256 actualSupply = supplyAmount;
        if (actualSupply > bal) {
            actualSupply = bal;
        }
        require(actualSupply > 0, "no funds to supply");

        // Setup: supply mAsset into the yield source, credited to this test contract.
        m.approve(address(c), actualSupply);
        c.supplyTokenTo(actualSupply, address(this));

        // Observable before-values via public surface only.
        uint256 creditsBefore = c.imBalances(address(this));
        uint256 rate = c.savings().exchangeRate();
        uint256 underlyingValueOfCredits = (creditsBefore * rate) / 1e18;

        // Decide redeem amount: enough to exceed the balance when possible (to test under-redeem),
        // otherwise the full underlying value.
        uint256 redeemArg = redeemAmount;
        if (redeemArg == 0) {
            redeemArg = underlyingValueOfCredits + 1;
        }

        uint256 mBalBefore = m.balanceOf(address(this));
        bool reverted;
        uint256 returned = 0;
        try c.redeemToken(redeemArg) returns (uint256 r) {
            returned = r;
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint256 creditsAfter = c.imBalances(address(this));
            uint256 mBalAfter = m.balanceOf(address(this));
            uint256 actualReceived = mBalAfter - mBalBefore;

            // General rule: a successful redeem can never pay out more underlying mAsset than the
            // user's credits were worth (pegged by the savings exchange rate), and can never burn
            // more credits than the user had.
            assert(returned == actualReceived);
            assert(actualReceived <= underlyingValueOfCredits);
            assert(creditsAfter <= creditsBefore);
        } else {
            // On a reverting redeem, the user's credit balance is untouched by the whole call.
            uint256 creditsAfterRevert = c.imBalances(address(this));
            assert(creditsAfterRevert == creditsBefore);
        }
    }
}

