contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 supplyAmount, address to, uint256 redeemAmount) public {
        require(supplyAmount > 0, "need positive supply");
        require(to != address(0), "need nonzero receiver");
        require(redeemAmount > 0, "need positive redeem");

        address savingsAddr = address(c.savings());
        IERC20 mAsset = c.mAsset();

        // Provide the contract with enough tokens to supply; raw transfer is fine for the setup.
        mAsset.transfer(address(c), supplyAmount);

        // Record receiver's credited balance before the supply.
        uint256 creditsBefore = c.imBalances(to);

        // Supply on behalf of `to`; this should credit `to`.
        c.supplyTokenTo(supplyAmount, to);

        uint256 creditsAfter = c.imBalances(to);

        // The credited balance must not decrease after a successful supply.
        assert(creditsAfter >= creditsBefore);

        // Redeem more than the credited balance would allow.
        // Either the call reverts (in which case c's imBalances(to) is unchanged),
        // or it succeeds and reflects a burn of at most the credited balance.
        bool reverted;
        try c.redeemToken(redeemAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            // A reverted redeem must leave the sender's (the test contract's) balance unchanged,
            // which for `to` = address(this) means the balance is still creditsAfter.
            if (to == address(this)) {
                assert(c.imBalances(address(this)) == creditsAfter);
            } else {
                assert(true);
            }
        } else {
            // A successful redeem must not leave a balance larger than the credited amount.
            assert(c.imBalances(address(this)) <= creditsAfter);
        }
    }

    receive() external payable {}
}

