            creditsBurned = imBalBefore - c.imBalances(address(this));
            imBalAfter = c.imBalances(address(this));
            mAssetBalAfter = IERC20(c.depositToken()).balanceOf(address(c));
            reverted = false;
        } catch {
            mAssetsActual = 0;
            creditsBurned = 0;
            imBalAfter = c.imBalances(address(this));
            mAssetBalAfter = IERC20(c.depositToken()).balanceOf(address(c));
            reverted = true;
        }

        assert(
            reverted
                ? imBalAfter == imBalBefore
                : creditsBurned == redeemAmount && mAssetBalAfter == mAssetBalBefore - mAssetsActual
        );
    }

    receive() external payable {}
}

